            "heading": "أحكام التلاوة: المد العارض للسكون (صفحة 4)",
            "text": "أحكام التلاوة: المد العارض للسكون\nهو مد حرف الألف أو الواو أو الياء (أحرف المد الثلاثة) بمقدار حركتين أو أربع أو ست حركات، عندما يسكن الحرف الأخير الذي يلي حرف المد في الكلمة بسبب الوقف لغرض التنفس أو انتهاء القراءة.\n\nفيكون السكون للحرف الأخير من الكلمة عارضاً بسبب الوقف. أما إذا لم نقف على الكلمة فلا يسكن الحرف الأخير، فيمد حرف المد مداً طبيعياً بمقدار حركتين.\n\nأمثلة توضيحية:\n1. ﴿الرَّحْمَٰنِ الرَّحِيمِ﴾ عند الوقف على كلمة (الرَّحِيمِ) تسكن الميم فيصبح الياء حرف مد عارض للسكون ويمد (2 أو 4 أو 6 حركات). أما عند الوصل: (الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ) فيمد مداً طبيعياً حركتين فقط.\n2. ﴿يَعْلَمُونَ﴾ عند الوقف تسكن النون، ويمد حرف الواو مداً عارضاً للسكون.\n3. ﴿النَّاسِ﴾ عند الوقف تسكن السين، ويمد حرف الألف مداً عارضاً للسكون.\n\nمقدار مده:\nيمد بمقدار حركتين (قصر) أو أربع حركات (توسط) أو ست حركات (طول / إشباع)."
