                    "q": "3. ما أمنيات الكفرة الظالمين يوم القيامة؟ ولماذا؟",
                    "a": "🎯 أمنية الكافر يوم القيامة:\nقوله تعالى في ختام السورة: ﴿وَيَقُولُ الْكَافِرُ يَا لَيْتَنِي كُنتُ تُرَابًا﴾ [النبأ: 40].\n\n💡 سبب هذه الأمنية:\nيتمنى الكافر لو كان تراباً من شدة هول الموقف وما يراه من عذاب جهنم وعظيم الحساب، وحين يرى الحيوانات التي لا تكليف عليها قد قُضي بينها وحُولت إلى تراب، فيتمنى لو كان تراباً مثلها لئلا يُبعث ولا يُحاسب ولا يُعذب في نار جهنم على كفره وتكذيبه."
