                    "a": "اقتضت حكمة الله البالغة أن تكون معجزة كل نبي من جنس ما نبغ وبرع فيه قومه ليكون التحدي أبلغ والإعجاز أقوى:\n1. معجزة موسى (عليه السلام): جاءت في عصر نبغ فيه المصريون في فن السحر، فجاءت عصاه التي تحولت إلى ثعبان حقيقي التهم حبالهم وعصيهم، فعلم السحرة الحذاق أن هذا ليس بسحر بل قدرة إلهية فخروا ساجدين.\n2. معجزة عيسى (عليه السلام): جاءت في عصر تطور فيه علم الطب والتداوي، فأبرأ الأكمه (الذي ولد أعمى) والأبرص وأحيا الموتى بإذن الله، وهو ما لا طاقة للطب البشري به إطلاقاً.\n3. معجزة محمد (صلى الله عليه وآله وسلم): جاءت في قوم بلغوا قمة الفصاحة والبلاغة والبيان ونظم المعلقات، فأنزل الله القرآن الكريم بلسانهم العربي المبين وأعجزهم عن الإتيان بسورة من مثله."
