                    "q": "4. ما معجزة رسول الله (ص) الخالدة؟ وكيف تحدى بها العرب وأهل البلاغة؟",
                    "a": "🎯 المعجزة الخالدة: هي (القرآن الكريم).\n\n💡 كيفية التحدي:\nتحدى الله به فصحاء العرب وبلغاءهم على مراحل متدرجة:\n- تحداهم أولاً أن يأتوا بمثل القرآن كله: ﴿قُل لَّئِنِ اجْتَمَعَتِ الْإِنسُ وَالْجِنُّ عَلَىٰ أَن يَأْتُوا بِمِثْلِ هَٰذَا الْقُرْآنِ لَا يَأْتُونَ بِمِثْلِهِ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا﴾.\n- ثم تحداهم أن يأتوا بعشر سور مثله مفتريات فعجزوا.\n- ثم تحداهم أن يأتوا بسورة واحدة من مثله: ﴿وَإِن كُنتُمْ فِي رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ﴾، فما استطاعوا وسجل التاريخ عجزهم المطلق وبقي القرآن معجزة خالدة أسلوباً وبلاغةً وتشريعاً وعلماً إلى يوم القيامة."
