            "text": "شروط صحة الصلاة:\n1. الإسلام والعقل والبلوغ (التمييز).\n2. دخول وقت الصلاة المحدد شرعاً.\n3. الطهارة من الحدثين (الأصغر بالوضوء والأكبر بالغسل) وطهارة البدن والثوب والمكان.\n4. ستر العورة.\n5. استقبال القبلة (الكعبة المشرفة).\n\nأركان الصلاة (التي تبطل الصلاة بتركها عمداً أو سهواً):\n1. النية. 2. تكبيرة الإحرام. 3. القيام مع القدرة. 4. قراءة الفاتحة. 5. الركوع والطمأنينة فيه. 6. الرفع من الركوع. 7. السجود على الأعضاء السبعة والطمأنينة فيه. 8. الجلوس بين السجدتين. 9. التشهد الأخير والجلوس له. 10. التسليم والترتيب والموالاة.\n\nمبطلات الصلاة:\n1. ترك ركن أو شرط من شروطها عمداً.\n2. الكلام العمد بغير ذكر الله.\n3. الأكل والشرب عمداً.\n4. الضحك بصوت (القهقهة).\n5. انتقاض الطهارة (الحدث).\n6. الحركة الكثيرة المتوالية لغير مصلحة الصلاة.\n7. الانحراف التام عن القبلة."
