            "text": "وصايا نبوية وأقوال الأئمة الأطهار في شأن الصلاة:\n- قال الإمام الصادق (عليه السلام): «أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ عَزَّ وَجَلَّ الصَّلَاةُ، وَهِيَ آخِرُ وَصَايَا الْأَنْبِيَاءِ».\n- وقال (عليه السلام): «لَا تَنَالُ شَفَاعَتُنَا مَنِ اسْتَخَفَّ بِالصَّلَاةِ».\nفالمسلم الحقيقي يعظم الصلاة ويؤديها في أوقاتها بخشوع وحضور قلب، متذكراً وقوفه بين يدي رب العالمين."
