                    "q": "1. ما آثار الصلاة الروحية والتربوية والاجتماعية في حياة المسلم؟",
                    "a": "1. تزكية النفس وتطهيرها من الذنوب والآثام.\n2. النهي عن الفحشاء والمنكر والتحلي بمكارم الأخلاق: ﴿إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ﴾.\n3. الشعور بالسكينة والطمأنينة والقرب من الله ومناجاته.\n4. تعويد المسلم على النظام والانضباط وإدارة الوقت.\n5. تعزيز روح المساواة والتآخي والتكافل الاجتماعي خاصة في صلاة الجماعة."
