            "text": "فتح مكة (رمضان 8 هـ):\nالسبب المباشر: نقض قريش لصلح الحديبية، حين أعانت حلفاءها من بني بكر ضد قبيلة خزاعة حليفة رسول الله (صلى الله عليه وآله وسلم)، فاستنجدت خزاعة بالرسول، فجهز جيشاً عظيماً قوامه عشرة آلاف مقاتل من المهاجرين والأنصار وقبائل العرب لفتح مكة وتطهير البيت الحرام من دنس الأصنام."
