            "heading": "دخول مكة والعفو النبوي التاريخي الخالد (صفحة 21)",
            "text": "دخول مكة وتحطيم الأصنام:\nدخل النبي (ص) مكة فاتحاً منصباً خاشعاً لله، يقرأ سورة الفتح ورأسه تكاد تمس رحل ناقته تواضعاً لله تعالى.\nطاف بالبيت الحرام وجعل يحطم الأصنام المنصوبة حول الكعبة بقوسه ويقول: ﴿جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا﴾.\n\nعفو الرسول العام:\nوقف أهل مكة مشدوهين يترقبون حكم النبي فيهم بعد عقود من التعذيب والتشريد والحروب، فقال لهم: «يَا مَعْشَرَ قُرَيْشٍ، مَا تَرَوْنَ أَنِّي فَاعِلٌ بِكُمْ؟» قالوا: خيراً، أخ كريم وابن أخ كريم. فقال كلمته الخالدة التي أذهلت البشرية: «اذْهَبُوا فَأَنْتُمُ الطُّلَقَاءُ». فعفا عنهم ع عفواً عاماً ودخل الناس في دين الله أفواجاً."
