            "heading": "عظم المصاب والتمسك بسنته والمناقشة (صفحة 24)",
            "text": "عظم المصاب وواجب المسلم:\nكانت وفاة النبي (ص) أعظم مصيبة حلت بالأمة الإسلامية، فكان الثبات على دينه وسنته هو الدواء. قال تعالى: ﴿وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ أَفَإِن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَىٰ أَعْقَابِكُمْ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ اللَّهَ شَيْئًا وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ﴾.\n\nالمناقشة:\nس1: ما هو سبب فتح مكة؟\nج1: نقض قريش لصلح الحديبية باعتدائهم على خزاعة حليفة المسلمين.\nس2: ماذا قال النبي (ص) لأهل مكة حين تجمعوا عند الكعبة؟\nج2: قال لهم: «اذهبوا فأنتم الطلقاء».\nس3: متى توفي النبي الكريم وما كانت آخر وصاياه؟\nج3: في 12 ربيع الأول سنة 11 هـ، وآخر وصاياه الصلاة وحسن معاملة الضعفاء ورعاية الحقوق.",
