                    "a": "🎯 تاريخ الوفاة: يوم الاثنين 12 من ربيع الأول سنة 11 للهجرة.\n🎯 عمره الشريف: ثلاث وستون (63) سنة قضاها في الدعوة والجهاد وبناء أمة الإسلام.\n🎯 من تولى غسله وتجهيزه: تولى غسله الإمام علي بن أبي طالب (عليه السلام) ومعه الفضل بن العباس وقثم بن العباس وأسامة بن زيد وصالح مولى النبي، وغُسل في قميصه تكريماً لجثمانه الطاهر، ثم صُلي عليه أرسالاً ودُفن في بيت عائشة حيث قبض."
