            "text": "آداب معاملة الناس:\nالإسلام دين الأخلاق والذوق الرفيع. وقد حث على آداب المعاشرة التي توثق عرى المحبة بين المسلمين:\n1. إفشاء السلام: رد التحية بأحسن منها أو بمثلها.\n2. طلاقة الوجه والتبسم: قال رسول الله (ص): «تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ».\n3. حسن الاستماع وعدم مقاطعة المتكلم حتى يكمل حديثه.\n4. التواضع وتجنب التكبر والتعالي على الناس."
