            "heading": "آداب المجالس والحديث (صفحة 26)",
            "text": "آداب المجالس:\n- التفسح في المجالس للقادم.\n- عدم إقامة شخص من مكانه للجلوس فيه.\n- تجنب التناجي (حديث اثنين سراً دون الثالث) لما فيه من إيحاش للقلب وإثارة للشك والحزن.\n- حفظ أسرار المجالس وأماناتها.\n- ختام المجلس بكفارة المجلس: (سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك)."
