            "heading": "آداب الطعام والشراب في الإسلام (صفحة 27)",
            "text": "آداب الطعام والشراب:\n- غسل اليدين قبل الطعام وبعده: قال الإمام علي (ع): «غسل اليدين قبل الطعام وبعده زيادة في الرزق والعمر».\n- التسمية في أوله وحمد الله في آخره.\n- الأكل باليد اليمنى ومما يليك من الطبق: قال النبي (ص) لعمر بن أبي سلمة: «يَا غُلَامُ، سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ».\n- تصغير اللقمة وإجادة المضغ وعدم النفخ في الطعام الحار أو الشراب.\n- عدم ذم الطعام، فإن اشتهاه أكله وإلا تركه."
