            "text": "الاعتدال في الطعام:\nنهى الإسلام عن الشره والتخمة، قال رسول الله (ص): «مَا مَلَأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ، بِحَسْبِ ابْنِ آدَمَ لُقَيْمَاتٌ يُقِمْنَ صُلْبَهُ، فَإِنْ كَانَ لَا مَحَالَةَ فَثُلُثٌ لِطَعَامِهِ، وَثُلُثٌ لِشَرَابِهِ، وَثُلُثٌ لِنَفَسِهِ».\nوتناول الطعام بقدر الحاجة يمنع الأمراض ويحفظ نشاط البدن والعقل."
