            "text": "مراعاة الذوق العام ونظافة المرافق:\n- المحافظة على نظافة الطرق والمدارس والحدائق والمساجد، وإماطة الأذى عن الطريق صدقة وشعبة من شعب الإيمان.\n- خفض الصوت في الأماكن العامة وتجنب الإزعاج.\n- مراعاة مشاعر الآخرين ومساعدتهم والرفق بالضعفاء وكبار السن.\n\nالمناقشة:\nس1: اذكر ثلاثة من آداب الطعام والشراب؟\nج1: التسمية في أوله والحمد في آخره، الأكل باليمين ومما يلي، وغسل اليدين قبله وبعده.\nس2: ما معنى حديث الرسول (ص): «تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ»؟\nج2: بيان أن طلاقة الوجه والبشاشة عمل صالح يثيب الله عليه كثواب الصدقة بالمال ويزرع الألفة بين المسلمين.",
