            "heading": "سورة القيامة: دلائل الخلق والمناقشة (صفحة 34)",
            "text": "خلق الإنسان والبرهان العقلي على البعث:\n﴿أَلَمْ يَكُ نُطْفَةً مِّن مَّنِيٍّ يُمْنَىٰ ﴿٣٧﴾ ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ ﴿٣٨﴾ فَجَعَلَ مِنْهُ الزَّوْجَيْنِ الذَّكَرَ وَالْأُنثَىٰ ﴿٣٩﴾ أَلَيْسَ ذَٰلِكَ بِقَادِرٍ عَلَىٰ أَن يُحْيِيَ الْمَوْتَىٰ ﴿٤٠﴾﴾:\nالذي خلق الإنسان من نطفة ضعيفة ثم علقة وسواه بشراً سوياً قادراً بلا شك على إحيائه بعد موته، فسبحان الخالق العظيم.\n\nأبرز ما ترشد إليه السورة:\n1. تقرير حقيقة البعث والجزاء والحساب بالبراهين العلمية والعقلية.\n2. تذكير الإنسان بأصله ونشأته ليتواضع ويخشع لربه.\n3. وجوب الاستعداد ليوم القيامة بالعمل الصالح قبل فوات الأوان.\n\nالمناقشة:\nس1: بم أقسم الله تعالى في مطلع السورة؟\nج1: أقسم بيوم القيامة وبالنفس اللوامة.\nس2: ما وجه الإعجاز في قوله تعالى: ﴿بَلَىٰ قَادِرِينَ عَلَىٰ أَن نُّسَوِّيَ بَنَانَهُ﴾؟\nج2: الإشارة إلى بصمات الأصابع الفريدة لكل إنسان التي يستحيل تطابقها، وقدرة الله على إعادة تشكيلها بدقة متناهية.",
