            "page": 37,
            "heading": "الحكمة من معجزات النبي والمناقشة (صفحة 37)",
            "text": "الحكمة من تنوع معجزات النبي (ص):\nجمع الله لنبيه بين المعجزة العقلية الخالدة الصالحة لكل زمان ومكان (القرآن)، والمعجزات الحسية المشاهدة لتثبيت المؤمنين وإقامة الحجة على المعاندين في عصره.\n\nالمناقشة:\nس1: ما الفرق بين معجزة القرآن الكريم وسائر معجزات الأنبياء السابقين؟\nج1: معجزات السابقين كانت حسية انقضت في أوقاتها، بينما القرآن معجزة عقلية بيانية علمية باقية وخالدة تتحدى العقول إلى يوم الدين.\nس2: اذكر معجزتين حسيّتين لرسول الله (ص)؟\nج2: انشقاق القمر، ونبع الماء الزلال من بين أصابعه الشريفة حتى كفى جيشاً كاملاً.",
