            "text": "أحكام وآداب:\n- يقرأ الإمام في الركعتين الأوليين وينصت المأمومون، بينما يقرأ المأمومون التسبيحات في الركعتين الأخيرتين سراً.\n- يجوز أداء صلاة الليل بأقل من إحدى عشرة ركعة كالشفع والوتر، ولكن تمامها أعظم أجراً.\n\nالمناقشة:\nس1: كم تفضل صلاة الجماعة على صلاة المنفرد؟\nج1: تفضلها بسبع وعشرين درجة.\nس2: ما هو أفضل أوقات صلاة الليل؟\nج2: الثلث الأخير من الليل (وقت السحر) قبيل صلاة الصبح.\nس3: ما عدد ركعات صلاة الليل الكاملة؟\nج3: إحدى عشرة ركعة (8 نافلة الليل، ركعتا الشفع، وركعة الوتر).",
