                    "q": "1. ما فضل صلاة الليل وعظيم ثوابها؟ استشهد بحديث نبوي شريف.",
                    "a": "صلاة الليل هي شرف المؤمن وعزه، وأفضل الصلاة بعد الفريضة، تنير الوجه والقلب، وتورث صحة البدن، وتبسط الرزق، وتكفر السيئات، وتستجلب رضوان الله تعالى ومباهاة الملائكة بالعبد القائم.\n\n📌 الحديث النبوي الشريف:\nقال رسول الله (صلى الله عليه وآله وسلم): «عليكم بقيام الليل فإنه دأب الصالحين قبلكم، ومقربة إلى ربكم، ومكفرة للسيئات، ومنهاة عن الإثم، ومطردة للداء عن الجسد»."
