            "text": "أخلاق رسول الله (ص):\nكان خلقه القرآن، وصفه ربه عز وجل بقوله: ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾ [القلم: 4].\nومن شمائله العطرة:\n1. لا يقطع على أحد حديثه: كان (ص) يصغي لمن يحدثه مقبلاً عليه بوجهه ولا يقاطعه حتى يفرغ من كلامه، أدباً وحلماً وسعة صدر.\n2. يتفقد أصحابه ويسأل عنهم: فإن كان أحدهم مريضاً عاده، وإن كان غائباً دعا له، وإن كان في ضيق أعانه.\n3. التواضع ولين الجانب: يجلس حيث انتهى به المجلس، ويجيب دعوة الحر والعبد."
