            "text": "بشاشة الوجه وحسن المعشر:\n- كان حلو المعشر، دائم التبسم، لا يلقى أحداً إلا ببشر وفرح، وقال (ص): «لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلِيقٍ».\n- عُرف بالصادق الأمين حتى قبل بعثته، وكان أعداؤه يضعون ودائعهم وأماناتهم عنده لعلمهم بوفائه المطلق.\n\nالمناقشة:\nس1: بم وصف الله تعالى أخلاق رسوله في سورة القلم؟\nج1: قال تعالى: ﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾.\nس2: اذكر نموذجاً لتواضع الرسول (ص) وخدمته لنفسه في بيته؟\nج2: كان يخصف نعله ويرقع ثوبه ويحلب شاته ويساعد أهله في شؤون البيت دون تكبر.",
