                    "a": "1. الرحمة والرأفة بالخلق: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ﴾.\n2. الصدق والأمانة: وكان يعرف قبل البعثة بـ (الصادق الأمين).\n3. التواضع ولين الجانب وخفض الجناح للمؤمنين والفقراء.\n4. الصبر والحلم والعفو عند المقدرة والصفح الجميل.\n5. الكرم والجود والإيثار وبذل النفس والمال في مرضاة الله."
