                    "a": "رفض النبي (ص) أن يدعو عليهم بالهلاك والانتقام، بل ضرب أروع أمثلة الرحمة والصبر قائلاً:\n«إني لم أُبعث لعّاناً، وإنما بُعثتُ رحمة، اللهم اهدِ قومي فإنهم لا يعلمون»."
