            "text": "الآداب الشخصية في الإسلام:\nحث الإسلام على تكامل شخصية المسلم في مظهرها وجوهرها:\nقال تعالى: ﴿قَدْ أَفْلَحَ مَن زَكَّاهَا ﴿٩﴾ وَقَدْ خَابَ مَن دَسَّاهَا ﴿١٠﴾﴾ [الشمس].\nفالمسلم يحرص على نظافة قلبه من الحسد والغل، ونظافة بدنه وثيابه من الأوساخ والروائح الكريهة، لأن النظافة من الإيمان والطهور شطر الإيمان."
