            "text": "آداب استخدام الإنترنت والتكنولوجيا:\n- شكر الله على نعمة العلم والاتصالات واستخدامها فيما ينفع (طلب العلم، صلة الرحم، الدعوة إلى الخير).\n- تجنب المواقع والأفكار الهدامة والمضللة التي تنشر الانحراف والشبهات.\n- احترام خصوصيات الناس وعدم التجسس أو نشر الشائعات أو الإساءة لأحد عبر وسائل التواصل الاجتماعي.\n\nالمناقشة:\nس1: ماذا يفعل المسلم عند العطاس وماذا يقول هو وسامعه؟\nج1: يغطي فمه ويخفض صوته ويقول: الحمد لله، ويشمته سامعه بقول: يرحمك الله، فيجيبه: يهديكم الله ويصلح بالكم.\nس2: كيف نوظف الإنترنت ووسائل الاتصال الحديثة توظيفاً إسلامياً نافعاً؟\nج2: في طلب العلم النافع والتواصل الإيجابي ونشر الخير والحذر من المواقع المنحرفة وحفظ أوقاتنا وخصوصيات الناس.",
