            "heading": "سورة المزمل: الشرح والبيان - فضل قيام الليل والترتيل (صفحة 55)",
            "text": "الشرح والبيان:\n1. النداء الإلهي للرسول (ص): ناداه الله بـ (المزمل) ملاطفة له، وأمره بقيام الليل إما نصفه أو ينقص منه إلى الثلث أو يزيد إلى الثلثين، إعداداً لروحه الزكية لتحمل أعباء الرسالة العظمى.\n2. ترتيل القرآن: أمر الله بترتيل القرآن ترتيلاً، أي قراءته بتؤدة وتفكر وخشوع، فالترتيل يعين على الفهم ويحرك القلوب.\n3. بركات ناشئة الليل: العبادة في الليل أهدأ للبال وأجمع للفكر، حيث تسكن الأصوات وتصفو الأرواح، فيلتقي اللسان والقلب على ذكر الله."
