            "text": "معجزات سيدنا موسى (عليه السلام):\nأرسل الله موسى (ع) إلى فرعون الذي طغى وادعى الربوبية واستعبد بني إسرائيل يذبح أبناءهم ويستحيي نساءهم.\nوأيده الله بمعجزات باهرة:\n1. العصا: كانت عصا عادية يتوكأ عليها ويهش بها على غنمه، فلما ألقاها بأمر الله انقلبت حية تسعى ثعباناً مبيناً يلقف ما صنع سحرة فرعون من حبال وعصي خيل للناس أنها تسعى، فلما رأى السحرة ذلك علموا أنه قدرة إلهية فخروا سجداً مؤمنين برب موسى وهارون."
