                    "a": "لما وصل موسى وقومه إلى شاطئ البحر الأحمر ولحقهم فرعون وجنوده، قال بنو إسرائيل: ﴿إِنَّا لَمُدْرَكُونَ﴾، فقال موسى بيقين راسخ: ﴿كَلَّا ۖ إِنَّ مَعِيَ رَبِّي سَيَهْدِينِ﴾. فأمره الله أن يضرب البحر بعصاه، فانفلق البحر اثني عشر مسلكاً وكان كل فرق كالطود العظيم. عبر موسى وقومه بسلام، ولما دخل فرعون وجنوده البحر أطبقت عليهم الأمواج فغرقوا جميعاً، وكانت العبرة أن الظلم والطغيان مآله الهلاك، وأن النصر حليف المؤمنين الصابرين."
