            "text": "أهم ما يرشد إليه الحديث الشريف:\n1. التأكيد القاطع على حقوق الإنسان في الإسلام وحماية دمه وماله وشرفه.\n2. ترسيخ مبدأ الأخوة الإسلامية وتجريم كل أشكال الاعتداء والعدوان.\n3. حفظ اللسان عن الغيبة والنميمة والقذف والتشهير بالآخرين.\n4. سلامة المجتمع وأمنه لا تتحقق إلا بصيانة هذه الحرمات الثلاث.\n\nالمناقشة:\nس1: ما هي الحرمات الثلاث التي أكد عليها الحديث الشريف؟\nج1: حرمة الدم، وحرمة المال، وحرمة العرض.\nس2: كيف نحافظ على حرمة عرض المسلم في حياتنا اليومية؟\nج2: بالكف عن الغيبة والنميمة وعدم تتبع عوراته أو نشر الشائعات الكاذبة عنه والدفاع عنه في غيابه.",
