                    "a": "قال رسول الله (صلى الله عليه وآله وسلم):\n«المسلمُ أخو المسلمِ، لا يَظْلِمُهُ، ولا يَخْذُلُهُ، ولا يَحْقِرُهُ، التَّقْوَى هاهُنا - ويُشِيرُ إلى صَدْرِهِ ثَلاثَ مَرَّاتٍ - بحَسْبِ امرِئٍ من الشَّرِّ أنْ يَحْقِرَ أخاهُ المُسْلِمَ، كُلُّ المُسْلِمِ على المُسْلِمِ حَرَامٌ: دَمُهُ، ومَالُهُ، وعِرْضُهُ»."
