                    "a": "🎯 معنى العِرْض: هو شرف الإنسان وكرامته وسمعته وسمعة أهله ومحارمه.\n🎯 واجب المسلم: حفظ عرض أخيه المسلم بعدم اغتيابه، أو بهتانه، أو قذفه، أو تتبع عوراته، بل يدافع عنه ويذب عن عرضه إذا ذُكر بسوء في غيابه، ويحفظ كرامته."
