            "heading": "وقت صلاة الآيات وأحكام القضاء والمناقشة (صفحة 67)",
            "text": "وقت صلاة الآيات:\nيبدأ وقتها من ابتداء حدوث الكسوف أو الخسوف إلى انجلائه وزواله، وتؤدى جماعة أو فرادى، ويستحب فيها إطالة القراءة والركوع والدعاء والاستغفار.\n\nالمناقشة:\nس1: متى تشرع صلاة الآيات؟\nج1: عند كسوف الشمس أو خسوف القمر أو حدوث الزلازل المخيفة.\nس2: كم ركوعاً وسجوداً في صلاة الآيات؟\nج2: فيها ركعتان، في كل ركعة خمسة ركوعات وسجدتان (أي عشرة ركوعات وأربع سجدات في مجموع الركعتين).",
