                    "a": "صلاة الآيات هي صلاة واجبة شرعاً يصليها المسلم عند حدوث ظواهر كونية غير اعتيادية تخيف الناس وتذكرهم بقدرة الله وعظمته، وسميت بـ (صلاة الآيات) لأنها تشرع عند ظهور الآيات الكونية المخوفة كالكسوف والخسوف والزلزلة."
