                    "q": "2. متى تجب صلاة الآيات؟ عدد أسباب وموجبات وجوبها.",
                    "a": "تجب صلاة الآيات في الحالات الآتية:\n1. كسوف الشمس (كلياً أو جزئياً).\n2. خسوف القمر (كلياً أو جزئياً).\n3. حدوث الزلازل والهزات الأرضية المخوفة.\n4. كل مخوف سماوي أو أرضي عام (كالريح السوداء الشديدة، والظلمة غير المعتادة، والصواعق الهائلة)."
