                    "q": "4. بيّن كيفية أداء صلاة الآيات بالتفصيل من الإحرام إلى التسليم.",
                    "a": "1. ينوي المصلي صلاة الآيات قربة إلى الله تعالى ويكبر تكبيرة الإحرام.\n2. يقرأ الفاتحة وسورة، ثم يركع الركوع الأول، ثم يرفع رأسه ويقرأ الفاتحة وسورة ويركع الركوع الثاني، ويكرر ذلك حتى يكمل خمسة ركوعات.\n3. بعد الرفع من الركوع الخامس يهوي إلى السجود فيسجد سجدتين كالصلوات اليومية.\n4. يقوم للركعة الثانية ويفعل فيها كما فعل في الأولى تماماً (قراءة وركوع 5 مرات).\n5. بعد الركوع الخامس يسجد سجدتين، ثم يتشهد ويسلّم."
