            "text": "الصحابي الجليل عمر بن الخطاب (رضي الله عنه):\nالفاروق، ثاني الخلفاء الراشدين، وأحد السابقين للإسلام. كان إسلامه عزاً للمسلمين وظهوراً لدعوتهم في مكة.\nلقبه النبي (ص) بالفاروق لأن الله فرق به بين الحق والباطل.\nاتصف بالقوة في الحق، والشجاعة الفائقة، والعدل المطلق الذي صار مضرب الأمثال في تاريخ البشرية."
