            "text": "مآثر الفاروق عمر بن الخطاب:\n1. العدل والمساواة: كان يراقب عماله وولاته ويحاسبهم بدقة، ويسهر بنفسه ليتفقد أحوال الرعية والفقراء والأرامل والأيتام.\n2. تأسيس الدواوين وتنظيم الدولة: دون الدواوين ووضع التقويم الهجري وأنشأ بيت المال ونظم القضاء.\n3. الزهد والتواضع: كان يلبس الثوب المرقع وينام تحت ظل شجرة دون حرس حتى قال له رسول كسرى: «عَدَلْتَ فَأَمِنْتَ فَنِمْتَ يَا عُمَرُ»."
