                    "a": "كانت السيدة عائشة من أعلم الناس بالقرآن والفرائض والسنة والطب والشعر، روت أكثر من ألفي حديث نبوي شريف، وكانت مرجعاً لكبار الصحابة في الفتوى وتفسير أحكام الأحوال الشخصية والعبادات والسنن البيتية النبوية."
