            "text": "نماذج خالدة من الإيثار:\n1. إيثار الأنصار للمهاجرين: حين هاجر المسلمون إلى المدينة بلا مال ولا مأوى، قاسمهم الأنصار دورهم وأموالهم وثمارهم بصدق وطيب نفس.\n2. موقف الصحابي الذي أضاف ضيف النبي: أطفأ السراج وتظاهر بأنه يأكل هو وزوجته ليطعم ضيف رسول الله، فنزل فيه قوله تعالى: ﴿وَيُؤْثِرُونَ عَلَىٰ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾.\n3. إيثار الماء في معركة اليرموك: حين استسقى الجرحى الثلاثة الماء، فكلما قُدم الماء لأحدهم أشار إلى أخيه حتى استشهدوا جميعاً قبل أن يشربوا ليؤثر كل واحد صاحبه."
