                    "a": "الغاية هي إخراج الناس من ظلمات الجهل والضلال إلى نور الهداية والتوحيد.\n\n📋 الوظائف الثلاث في قوله تعالى: ﴿هُوَ الَّذِي بَعَثَ فِي الْأُمِّيِّينَ رَسُولًا مِّنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ﴾:\n1. تلاوة آيات الله القرآنية وإسماعها للناس بالحجة والبيان.\n2. تزكية النفوس وتطهيرها من الشرك ومساوئ الأخلاق.\n3. تعليمهم الكتاب (القرآن) والحكمة (السنة النبوية والفقه في الدين ومقاصد الشريعة)."
