                    "a": "شبّههم الله تعالى بالحمار الذي يحمل على ظهره كتباً نافعة ومجلدات علمية ثمينة ولكنه لا يفقه ما فيها ولا يستفيد منها شيئاً سوى التعب والثقل:\n- قال تعالى: ﴿مَثَلُ الَّذِينَ حُمِّلُوا التَّوْرَاةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ الْحِمَارِ يَحْمِلُ أَسْفَارًا ۚ بِئْسَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِ اللَّهِ﴾.\n- دلالة المثل: التحذير الصارم من تعلم العلم وحفظ النصوص دون العمل بها وتطبيقها على أرض الواقع."
