            "text": "معجزات الطب والإحياء بإذن الله:\n2. خلق كهيئة الطير: كان يصنع من الطين تمثال طير فينفخ فيه فيصير طيراً حقيقياً يطير بإذن الله.\n3. إبراء الأكمه والأبرص: كان يمسح على الأكمه (الذي وُلد أعمى فاقداً للبصر) فيبصر، وعلى الأبرص فيبرأ من جلده، وهو ما عجز عنه أعظم أطباء عصره.\n4. إحياء الموتى بإذن الله: كان يدعو الله فيخرج الميت من قبره حياً شاهداً بصدق رسالته.\n5. الإنباء بالغيب: كان يخبر الناس بما يأكلون في بيوتهم وما يدخرون من أطعمة ومقتنيات دون أن يراها.\n\nالمناقشة:\nس1: اذكر معجزتين لسيدنا عيسى (ع) في مجال إبراء الأمراض والإحياء؟\nج1: إبراء الأكمه والأبرص، وإحياء الموتى بإذن الله تعالى.\nس2: لماذا كانت معجزات عيسى (ع) متصلة بالطب وشفاء الأمراض المستعصية؟\nج2: لأن قومه بنو إسرائيل كانوا قد برعوا في الطب وعلم الأبدان، فجاءت معجزته تفوق علومهم ليعلموا أنها من الله الخالق.",
