                    "q": "4. ما الدلالة العقدية الهامة لتكرار قوله تعالى: ﴿بِإِذْنِي﴾ في معرض ذكر معجزات عيسى (ع)؟",
                    "a": "دلالتها نفي صفة الألوهية والربوبية والشرك عن عيسى (عليه السلام)، وتأكيد أنه عبد من عباد الله ورسول مكرم، وأن كل تلك الخوارق والمعجزات وقعت بمشيئة الله المطلقة وإذنه وقدرته لا بقدرة ذاتية مستقلة لعيسى، لإبطال مزاعم من ادعى فيه الألوهية أو البنوة."
