            "text": "فوائد الصوم وآثاره:\n1. الفوائد الروحية والتربوية: تعويد النفس على الصبر، وقمع الشهوات، وتقوية الإرادة ومراقبة الله، واستشعار جوع الفقراء والمساكين فترق القلوب لعونهم.\n2. الفوائد الصحية: يريح الجهاز الهضمي، ويطهر البدن من السموم والفضلات، وينظم نسبة السكر والدهون في الدم، وصدق رسول الله (ص) إذ قال: «صُومُوا تَصِحُّوا».\n\nالمناقشة:\nس1: عرف الصوم شرعاً؟\nج1: هو الإمساك بنية القربة عن جميع المفطرات من طلوع الفجر إلى غروب الشمس.\nس2: اذكر ركني الصوم الأساسيين؟\nج2: النية، والإمساك عن المفطرات من الفجر للمغرب.\nس3: عدد ثلاثة من مبطلات الصوم؟\nج3: الأكل والشرب عمداً، تعمد القيء، والحيض والنفاس.",
