            "text": "عثمان بن عفان (رضي الله عنه):\nثالث الخلفاء الراشدين، وأحد السابقين إلى الإسلام وبشره النبي بالجنة.\nلُقب بـ «ذي النورين» لأنه تزوج ابنتي رسول الله (صلى الله عليه وآله وسلم) رقية ثم بعد وفاتها تزوج أم كلثوم.\nاشتهر بشدة الحياء وكرم النفس، حتى قال عنه النبي (ص): «أَلَا أَسْتَحِي مِنْ رَجُلٍ تَسْتَحِي مِنْهُ الْمَلَائِكَةُ»."
