            "text": "جوده وإنفاقه في سبيل الله:\n- جهز جيش العسرة في غزوة تبوك بمال عظيم، فقدم ثلاثمائة بعير بأحلاسها وأقتابها وألف دينار، فقال النبي (ص): «مَا ضَرَّ عُثْمَانَ مَا عَمِلَ بَعْدَ الْيَوْمِ».\n- اشترى بئر رومة من رجل يهودي وجعل ماءها عذباً مباحاً للمسلمين جميعاً.\n- أهم أعماله في الخلافة: جمع القرآن الكريم على حرف واحد ومصحف إمام (مصحف عثمان) ونسخه وإرساله للأمصار لتوحيد قراءة المسلمين، وواصل الفتوحات الإسلامية حتى استشهد سنة 35 هـ."
