            "heading": "ثانياً: جعفر بن أبي طالب (رضي الله عنه) - نسبه وهجرة الحبشة (صفحة 92)",
            "text": "جعفر بن أبي طالب (رضي الله عنه):\nابن عم رسول الله (ص) وشقيق أمير المؤمنين علي بن أبي طالب (ع). من السابقين الأولين إلى الإسلام.\nكان شبيهاً بالنبي خَلْقاً وخُلُقاً، قال له النبي (ص): «أَشْبَهْتَ خَلْقِي وَخُلُقِي».\nقائد مهاجري الحبشة:\nلما اشتد تعذيب قريش للمستضعفين، هاجر جعفر على رأس المسلمين إلى الحبشة، وكان سفيراً بليغاً للإسلام أمام ملكها العادل النجاشي."
