            "heading": "خطبة جعفر التاريخية أمام النجاشي وبلاغة الإسلام (صفحة 93)",
            "text": "خطبة جعفر الخالدة أمام النجاشي:\nحين جاء وفد قريش يطلب تسليم المسلمين، وقف جعفر بكل شجاعة وقال:\n«أَيُّهَا الْمَلِكُ، كُنَّا قَوْمًا أَهْلَ جَاهِلِيَّةٍ، نَعْبُدُ الْأَصْنَامَ، وَنَأْكُلُ الْمَيْتَةَ، وَنَأْتِي الْفَوَاحِشَ، وَنَقْطَعُ الْأَرْحَامَ، وَنُسِيءُ الْجِوَارَ، يَأْكُلُ الْقَوِيُّ مِنَّا الضَّعِيفَ، حَتَّى بَعَثَ اللَّهُ إِلَيْنَا رَسُولًا مِنَّا، نَعْرِفُ نَسَبَهُ وَصِدْقَهُ وَأَمَانَتَهُ وَعَفَافَهُ، فَدَعَانَا إِلَى اللَّهِ لِنُوَحِّدَهُ وَنَعْبُدَهُ، وَأَمَرَنَا بِصِدْقِ الْحَدِيثِ، وَأَدَاءِ الْأَمَانَةِ، وَصِلَةِ الرَّحِمِ، وَحُسْنِ الْجِوَارِ...».\nفبكى النجاشي وقال: «إن هذا والذي جاء به عيسى ليخرج من مشكاة واحدة»، ورفض تسليمهم."
