                    "a": "🎯 السبب: قتل شرحبيل بن عمرو الغساني (عامل الروم) للحارث بن عمير الأزدي رسول النبي (ص) وكان قتل الرسل في الأعراف جريمة وإعلان حرب.\n🎯 البطولة والشهادة: تولى جعفر القيادة بعد استشهاد زيد بن حارثة، فقاتل بفروسية نادرة وسط جيش الروم البالغ مائتي ألف مقاتل، وقُطعت يمينه فأمسك الراية بيساره، ثم قُطعت يساره فاحتضن الراية بعضديه وصدره لتبقى عالية حتى استشهد ووجد في مقدمة جسده الشريف أكثر من تسعين طعنة ورمية رمح ليس فيها طعنة واحدة من دبر."
