            "text": "نماذج عملية للاعتدال في حياة الطالب:\n- الترشيد في استخدام الماء والكهرباء في البيت والمدرسة.\n- عدم رمي بقايا الطعام والاستفادة منها وحفظ النعمة.\n- شراء ما يحتاجه الطالب فعلاً من المستلزمات والملابس دون مباهاة وتبذير.\n\nالمناقشة:\nس1: ما الفرق بين الإسراف والتبذير؟\nج1: الإسراف مجاوزة الحد في المباح، والتبذير إنفاق المال في المعصية وغير وجه الحق.\nس2: اذكر آية قرآنية تصف المسرفين والمبذرين؟\nج2: قال تعالى: ﴿إِنَّ الْمُبَذِّرِينَ كَانُوا إِخْوَانَ الشَّيَاطِينِ وَكَانَ الشَّيْطَانُ لِرَبِّهِ كَفُورًا﴾.",
