            "text": "كونوا أنصار الله:\n﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا أَنصَارَ اللَّهِ كَمَا قَالَ عِيسَى ابْنُ مَرْيَمَ لِلْحَوَارِيِّينَ مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ...﴾ [الآية 14].\nدعوة لجميع المؤمنين ليكونوا دعاة حق وأنصاراً لعدالة الله كما كان الحواريون الأطهار مع المسيح عيسى (ع)."
