            "text": "أهم ما ترشد إليه السورة:\n1. وجوب مطابقة القول للعمل، وتحريم النفاق والخداع في الوعود.\n2. قوة الأمة الإسلامية في وحدة كلمتها وتراص صفوفها كالبنيان المرصوص.\n3. نور الإسلام ودينه منصور بعون الله ولن يستطيع أحد إطفاءه مهما كاد الكائدون.\n4. الإيمان والجهاد بالمال والنفس هما أعظم تجارة رابحة مع الله تفضي إلى جنات النعيم.\n\nالمناقشة:\nس1: لماذا مقت الله تعالى الذين يقولون ما لا يفعلون؟\nج1: لأن اختلاف القول عن الفعل نفاق وخداع يضعف الثقة بين الناس ويهدم قيم الصدق والوفاء.\nس2: ما هي عناصر التجارة الرابحة المذكورة في سورة الصف؟\nج2: الإيمان بالله ورسوله، والجهاد في سبيل الله بالمال والنفس.",
