            "text": "أسماء بنت أبي بكر الصديق (رضي الله عنها):\nابنة الخليفة الأول أبي بكر الصديق، وأخت أم المؤمنين عائشة، وزوجة الزبير بن العوام، وأم عبد الله بن الزبير.\nنشأت في بيت الإيمان والصدق، وكانت من السابقات إلى الإسلام (أسلمت بعد 17 صحابياً).\nلقبها: «ذات النطاقين»:\nأطلق عليها رسول الله (ص) هذا اللقب يوم الهجرة النبوية، حين صنعت للنبي ولأبيها زاداً في رحلة الهجرة، فلم تجد ما تربط به سفرة الطعام وقربة الماء، فشقت نطاقها (حزام ثوبها) نصفين فربطت بهما، فدعا لها النبي ببدلهما نطاقين في الجنة."
