            "heading": "ثانياً: الصحابي الجليل جليبيب الأنصاري (رضي الله عنه) (صفحة 115)",
            "text": "جليبيب الأنصاري (رضي الله عنه):\nصحابي جليل وفقير متواضع من أهل الصفة، كان يعتز بإيمانه ونقائه.\nعطف رسول الله عليه وتزويجه:\nنظر النبي (ص) إليه بعين الرحمة والرعاية وعرض عليه الزواج، وخطب له بنفسه فتاة من أشرف بيوت الأنصار، فامتثلت الفتاة وأبوها لأمر رسول الله وقالت: «أتردون على رسول الله أمره؟! ادفعوني إليه فإنه لن يضيعني». فدعا لها النبي بالبركة فكانت من أنفق بيوت الأنصار.\n\nبطولته الخارقة واستشهاده:\nخرج جليبيب مع رسول الله في إحدى الغزوات، وقاتل بشجاعة واستبسال، فقتل سبعة من المشركين ثم استشهد. فتفقده النبي بعد المعركة وقال: «لكني أفقد جليبيباً»، فوجدوه بين قتلاه، فوقف عليه النبي وبكى ووضعه على ساعديه وقال كلمته الخالدة التي خلدت اسمه في التاريخ: «هَذَا مِنِّي وَأَنَا مِنْهُ، هَذَا مِنِّي وَأَنَا مِنْهُ»، ودفنه بنفسه الشريفة.\n\nالمناقشة:\nس1: لماذا سميت أسماء بنت أبي بكر بـ «ذات النطاقين»؟\nج1: لأنها شقت نطاقها نصفين لتربط بهما طعام وسقاء رسول الله وأبيها في الهجرة.\nس2: ماذا قال النبي (ص) في حق جليبيب الأنصاري عند استشهاده؟\nج2: قال مكرراً: «هَذَا مِنِّي وَأَنَا مِنْهُ» تكريماً لإيمانه وجهاده.",
