                    "a": "كانت أسماء تنقل الطعام والشراب وأخبار قريش سراً إلى رسول الله (ص) وأبيها في غار ثور ليلاً وهي حامل في ظلمات الصحراء مخاطرة بحياتها. ولما أرادت ربط سفرة الطعام وقربة الماء لم تجد رباطاً، فشقت نطاقها (حزامها) نصفين فربطت بأحدهما الزاد وبالآخر السقاء، فسماها رسول الله (ص) بـ (ذات النطاقين) وبشرها بنطاقين في الجنة."
