                    "a": "وقفت أسماء كالطود الشامخ ورفضت الإفصاح عن سرهما، فلطمها أبو جهل لطمة شديدة أطارت قرطها من أذنها، فصبرت ولم تضعف ولم تنبس ببنت شفة، محافظة على سر هجرة المصطفى (ص)."
