                    "a": "هو صحابي جليل من الأنصار، كان فقيراً دميماً رث الثياب لا يعرف له نسب في قريش، وكان الناس يزهدون فيه، لكن رسول الله (ص) عرف نقاء قلبه وصدق إيمانه فقال له: «لكنك عند الله لست بكاسد»، وزوجه النبي بنفسه من فتاة مؤمنة، فكان رمزاً لإسقاط المعايير الجاهلية وتأكيد أن ميزان التفاضل في الإسلام هو التقوى."
