            "text": "صلة الرحم:\nمعناها: الإحسان إلى الأقارب وذوي القربى بالزيارة والمودة وتفقد أحوالهم، وإيصال الخير والنفع المالي والمعنوي إليهم، ودفع الأذى والشر عنهم.\nفضلها ومكانتها:\nصلة الرحم من أعظم الواجبات الشرعية، قرن الله تعالى الأمر بها بعبادته وتوحيده: ﴿وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا﴾ [النساء: 1].\nوقال رسول الله (ص): «مَنْ سَرَّهُ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَأَنْ يُنْسَأَ لَهُ فِي أَثَرِهِ (عُمُرِهِ)، فَلْيَصِلْ رَحِمَهُ»."
