            "text": "عقوبة قطيعة الرحم:\nقطيعة الرحم من كبائر الذنوب التي تجلب مقت الله وعقوبته العاجلة في الدنيا قبل الآخرة:\n- قال رسول الله (ص): «لَا يَدْخُلُ الْجَنَّةَ قَاطِعُ رَحِمٍ».\n- قاطع الرحم ممقوت منبوذ من الناس، يمحق الله بركة رزقه وعمره، ولا ترفع له دعوة.\n- قال تعالى محذراً: ﴿فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ ﴿٢٢﴾ أُولَٰئِكَ الَّذِينَ لَعَنَهُمُ اللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰ أَبْصَارَهُمْ ﴿٢٣﴾﴾ [محمد].\n\nالمناقشة:\nس1: ما هو فضل صلة الرحم كما بينه النبي الكريم؟\nج1: بسطة وسعة في الرزق، وبركة وزيادة في العمر والأثر الطيب، ونيل الجنة.\nس2: من هو الواصل الحقيقي في ميزان الإسلام؟\nج2: هو الذي يصل رحمه إذا قُطعت ويعفو عمن أساء إليه ابتغاء مرضاة الله.",
